interface HasId {
  id: number;
}

function show(item: HasId): string {
  return `#${item.id}`;
}

const task = { id: 3, title: "Write quiz" };
console.log(show(task));

type Result = { ok: true; value: number } | { ok: false; error: string };

function show(result: Result): string {
  return result.ok ? `value ${result.value}` : `error ${result.error}`;
}

console.log(show({ ok: false, error: "nope" }), show({ ok: true, value: 7 }));
